// The message catalogs of locales/ for the specs, which look up the names they expect in the project's locale.
// A namespace is a directory of area files (ADR-0082); the client pseudo-locales are generated by i18n:gen-ts.
import { readdirSync, readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

/** A catalog in the FormatJS JSON shape: message key → entry. */
export type Catalog = Record<string, { defaultMessage: string }>;

const catalogs = new Map<string, Catalog>();

/** Every message of the `namespace` catalog of `locale`, merged from its area files. */
export function readCatalog(locale: string, namespace = "client"): Catalog {
  const dir = fileURLToPath(new URL(`../../../locales/${locale}/${namespace}/`, import.meta.url));
  let catalog = catalogs.get(dir);
  if (catalog === undefined) {
    const files = readdirSync(dir, { recursive: true, encoding: "utf8" }).filter((f) => f.endsWith(".json"));
    catalog = Object.assign(
      {},
      ...files.map((f) => JSON.parse(readFileSync(`${dir}${f}`, "utf8")) as Catalog),
    ) as Catalog;
    catalogs.set(dir, catalog);
  }
  return catalog;
}
